/* ============================================================================
 * TapMyCar  Patch  Real Help & FAQ page
 *
 * BUG: the "Help & FAQ" row in settings opened a mailto: link  there was
 * no actual help page.
 *
 * FIX:
 *  1. Creates public/help.html  full FAQ page with 27 questions across 6
 *     categories (Getting started, Your sticker, How calls work, Billing &
 *     plans, Privacy & safety, Account & troubleshooting), live search,
 *     accordion expand-on-tap, and a "still stuck? email us" footer.
 *  2. Rewires the settings.html "Help & FAQ" row to point at /help.html
 *     instead of the mailto: link. Icon and subtitle updated to match.
 *
 * Uses the same tmcSmartBack() back-button helper from the smart-back patch
 * so back navigation behaves correctly from any entry point.
 *
 * Run from project root:  node tapmycar-patch-help-faq.js
 * Safe to re-run.
 * ==========================================================================*/
'use strict';
const fs = require('fs');
const path = require('path');

const STAMP = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');
const BACKUP_DIR = 'backup-help-faq-' + STAMP;

const FILES = {
  'public/help.html':     "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<title>Help & FAQ — TapMyCar</title>\n<meta name=\"description\" content=\"Frequently asked questions about TapMyCar — billing, your sticker, calls, privacy, and more.\">\n\n<link rel=\"icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n\n<style>\n.help-page { max-width: 720px; margin: 0 auto; padding: 24px 16px 80px; }\n.help-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }\n.help-h1 { font-size: 28px; font-weight: 800; color: #111; letter-spacing: -.5px; margin: 0 0 6px; }\n.help-sub { font-size: 14px; color: #6B7280; line-height: 1.55; margin: 0 0 22px; }\n.help-search { position: relative; margin: 0 0 24px; }\n.help-search input {\n  width: 100%; padding: 13px 14px 13px 42px; font-size: 14px;\n  border: 1.5px solid #E5E7EB; border-radius: 12px;\n  background: #fff; color: #111; font-family: inherit;\n  -webkit-appearance: none; appearance: none; box-sizing: border-box;\n  transition: border-color .2s ease, box-shadow .2s ease;\n}\n.help-search input:focus { outline: none; border-color: #FF6B00; box-shadow: 0 0 0 4px rgba(255,107,0,.1); }\n.help-search svg { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); width: 18px; height: 18px; color: #9CA3AF; pointer-events: none; }\n.help-section { margin: 0 0 22px; }\n.help-section-h { font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .12em; color: #FF6B00; margin: 0 0 10px; padding: 0 4px; }\n.help-item {\n  background: #fff; border: 1px solid #E5E7EB; border-radius: 12px;\n  margin: 0 0 8px; overflow: hidden;\n  transition: border-color .2s ease, box-shadow .25s ease;\n}\n.help-item:hover { border-color: #FED7AA; }\n.help-item.open { border-color: #FF6B00; box-shadow: 0 6px 18px rgba(255,107,0,.1); }\n.help-q {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 14px 16px; cursor: pointer;\n  font-size: 14px; font-weight: 700; color: #111; line-height: 1.4;\n  gap: 12px; -webkit-tap-highlight-color: transparent;\n}\n.help-q-chev { width: 18px; height: 18px; color: #FF6B00; flex: 0 0 18px; transition: transform .25s ease; }\n.help-item.open .help-q-chev { transform: rotate(180deg); }\n.help-a {\n  max-height: 0; overflow: hidden;\n  transition: max-height .35s ease, padding .25s ease;\n  padding: 0 16px; font-size: 13px; color: #4B5563; line-height: 1.65;\n}\n.help-item.open .help-a { max-height: 600px; padding: 0 16px 14px; }\n.help-a p { margin: 0 0 8px; }\n.help-a p:last-child { margin: 0; }\n.help-a a { color: #FF6B00; font-weight: 600; text-decoration: none; }\n.help-a a:hover { text-decoration: underline; }\n.help-a ul { margin: 6px 0 8px; padding: 0 0 0 18px; }\n.help-a li { margin: 0 0 4px; }\n.help-a strong { color: #111; font-weight: 700; }\n.help-noresults { text-align: center; padding: 28px 12px; color: #9CA3AF; font-size: 13px; display: none; }\n.help-noresults.show { display: block; }\n\n.help-contact {\n  margin: 28px 0 0; padding: 20px;\n  background: linear-gradient(135deg, #FFF7ED 0%, #FFE4CC 100%);\n  border: 1px solid #FED7AA; border-radius: 14px;\n  text-align: center;\n}\n.help-contact-h { font-size: 15px; font-weight: 800; color: #7C2D12; margin: 0 0 4px; }\n.help-contact-s { font-size: 12px; color: #9A3412; margin: 0 0 14px; line-height: 1.55; }\n.help-contact a {\n  display: inline-flex; align-items: center; gap: 8px;\n  background: #FF6B00; color: #fff;\n  font-size: 13px; font-weight: 700;\n  padding: 11px 18px; border-radius: 10px;\n  text-decoration: none;\n  box-shadow: 0 6px 16px rgba(255,107,0,.3);\n  transition: transform .15s ease, box-shadow .15s ease;\n}\n.help-contact a:active { transform: translateY(1px); box-shadow: 0 3px 8px rgba(255,107,0,.3); }\n</style>\n</head>\n\n<body class=\"wide-page\">\n<div class=\"help-page\">\n\n  <div class=\"help-hdr\">\n    <a href=\"/\" aria-label=\"TapMyCar\"><img src=\"/logo.png\" alt=\"TapMyCar\" style=\"height:44px;width:auto;display:block\"></a>\n    <a href=\"javascript:void(0)\" onclick=\"tmcSmartBack('/')\" class=\"back-link\" style=\"margin:0\">← Back</a>\n  </div>\n\n  <h1 class=\"help-h1\">Help & FAQ</h1>\n  <p class=\"help-sub\">Quick answers about how TapMyCar works, billing, your sticker, and your privacy. Tap any question to expand. Still stuck? Email us — link at the bottom.</p>\n\n  <div class=\"help-search\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\n    <input type=\"search\" id=\"help-q-input\" placeholder=\"Search questions…\" autocomplete=\"off\">\n  </div>\n\n  <div id=\"help-list\">\n\n    <!-- GETTING STARTED -->\n    <div class=\"help-section\" data-section=\"Getting started\">\n      <div class=\"help-section-h\">Getting started</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What is TapMyCar?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>TapMyCar is a privacy-first contact platform for your vehicle. You stick a small NFC + QR sticker on your windshield. If someone needs to reach you about your car — for example to ask you to move it, or to report damage — they tap or scan the sticker and call you through our system. <strong>Your real phone number stays hidden</strong> the entire time.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How do I get started?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Two ways:</p><ul><li><strong>Free eTag</strong> — sign up, download your digital tag, and try TapMyCar without a card.</li><li><strong>Physical sticker</strong> — pick Standard or Premium on the <a href=\"/pricing.html\">pricing page</a>. Your sticker ships in 2–3 business days.</li></ul></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do I need an app?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>No. TapMyCar works in any modern phone browser. You manage your tag, calls, and settings from <a href=\"/dashboard.html\">tapmycar.io</a>. Strangers scanning your sticker don't need an app either — the NFC tap or QR scan opens the call page directly.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Does it work on iPhone and Android?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes, both. iPhones (iOS 14 and newer) and Android phones can read the NFC tag with a normal tap. Older devices can still use the QR code printed on every sticker. No app install needed on either side.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Is there a free version?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes — the <strong>eTag</strong> is free to download and works the same way the sticker does: masked calls, screening, your number stays hidden. You can print it or display it however you like. The eTag becomes active for $1 so we can route calls; physical stickers add the actual sticker shipped to your door.</p></div></div>\n    </div>\n\n    <!-- YOUR STICKER -->\n    <div class=\"help-section\" data-section=\"Your sticker\">\n      <div class=\"help-section-h\">Your sticker</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What's in the sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Each sticker has a small embedded NFC chip <strong>and</strong> a printed QR code. Both link to your private call page. The sticker is weatherproof, designed to live on the inside of your windshield.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Where should I put the sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>The inside of your windshield, lower passenger-side corner is the most common spot. Some people place it on the driver-side dashboard. The key is that it's visible to anyone standing outside the car and that the QR + NFC area isn't blocked.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How long does shipping take?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Physical stickers ship within 2–3 business days. We mail in the US only at the moment.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Can I have stickers on more than one car?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. The <strong>Premium</strong> plan ships 3 stickers — handy if you have multiple vehicles, share a household, or want a spare. Each sticker is linked to your single account so all calls go to you.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What if my sticker is damaged or stolen?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Email <a href=\"mailto:support@tapmycar.io\">support@tapmycar.io</a> and we'll deactivate the missing tag and send a replacement. Even if someone steals the sticker, your real phone number never goes with it — they only get a routing link that we can revoke.</p></div></div>\n    </div>\n\n    <!-- HOW CALLS WORK -->\n    <div class=\"help-section\" data-section=\"How calls work\">\n      <div class=\"help-section-h\">How calls work</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What happens when someone scans my sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>The scanner is taken to a simple page on their phone with a \"Call owner\" button. When they tap it, our system places a masked call through to you. They never see your real number, and you can decide whether to answer.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Does the caller ever see my real phone number?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p><strong>No.</strong> Every call is routed through a TapMyCar number. The other person only sees that intermediate number — never yours. You also can't be reached at your real number by anyone who has just the sticker.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Can I screen calls before answering?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. Every incoming TapMyCar call lets you screen who's calling before you pick up. You can answer, decline, or let it go to voicemail — your choice, every time.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do I get notified when someone scans my sticker?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. Every scan shows up in your dashboard in real time with timestamp and approximate location (if the scanner allows). If they place a call, you also get the call right then. You can review your scan history any time from the <a href=\"/activity.html\">activity page</a>.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What if I'm not available to answer?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>The call simply goes unanswered, like any phone call. The scan still gets logged in your dashboard so you can see who tried to reach you and when. We do not relay text messages to your real phone number.</p></div></div>\n    </div>\n\n    <!-- BILLING -->\n    <div class=\"help-section\" data-section=\"Billing & plans\">\n      <div class=\"help-section-h\">Billing & plans</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How much does TapMyCar cost?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p><strong>Free eTag:</strong> free to download. $1 activation to enable masked calls.</p><p><strong>Standard:</strong> $9.99 for the sticker (shipped immediately) and then $9.99/year starting on day 30. Renews yearly.</p><p><strong>Premium:</strong> $24.99 for 3 stickers and then $19.99/year starting on day 30. Renews yearly.</p><p>Full details on the <a href=\"/pricing.html\">pricing page</a>.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">When does my annual subscription start?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>On day 30 after you pick a paid plan. That gives you a full month to try TapMyCar before the annual fee kicks in. You can cancel any time before day 30 in <a href=\"/settings.html\">Settings</a> and you'll only have paid the sticker fee.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How do I cancel?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Go to <a href=\"/billing.html\">Plan & Billing</a> in your Settings and tap \"Cancel plan.\" You stay active until the end of the period you've already paid for — no surprise cutoffs.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What's your refund policy?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Refunds available within 14 days of any annual charge — a $1 service fee is retained. After 14 days the plan is non-refundable for that period. Activation fees and sticker fees are non-refundable. Cancel anytime to stop future charges.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Can I upgrade from Standard to Premium?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Yes. In <a href=\"/billing.html\">Plan & Billing</a> there's an \"Upgrade to Premium\" option. You'll be charged for the 2 additional stickers and any prorated difference on the annual plan. Your existing sticker stays active.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do you accept which payment methods?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>All major credit and debit cards, plus Apple Pay and Google Pay where supported. Payments are processed securely by Stripe — we never see or store your full card details.</p></div></div>\n    </div>\n\n    <!-- PRIVACY & SAFETY -->\n    <div class=\"help-section\" data-section=\"Privacy & safety\">\n      <div class=\"help-section-h\">Privacy & safety</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Who can see my phone number?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Only TapMyCar (so we can route calls to you). Not strangers who scan your sticker, not other users, not anyone else. Calls are masked at the carrier level — your number is never transmitted to the caller.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">What data do you collect?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Only what's needed to run the service: your phone number, sign-in email, billing details (handled by Stripe), and a log of scans and calls on your sticker so you can see your activity. Full details in our <a href=\"/privacy.html\">Privacy Policy</a>.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Do you share or sell my information?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>No. We don't sell your data and we don't share it for advertising. The only third parties we share with are the service providers that help us run TapMyCar — Twilio for masked calls, Stripe for payments, etc. See the <a href=\"/privacy.html\">Privacy Policy</a> for the full list.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">Is the call recorded?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>No. We do not record or transcribe TapMyCar calls. We log only the call metadata (timestamp, masked number used, duration) so you can see your call history.</p></div></div>\n    </div>\n\n    <!-- ACCOUNT & TROUBLESHOOTING -->\n    <div class=\"help-section\" data-section=\"Account & troubleshooting\">\n      <div class=\"help-section-h\">Account & troubleshooting</div>\n\n      <div class=\"help-item\"><div class=\"help-q\">I changed my phone number — what do I do?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Go to <a href=\"/settings.html\">Settings</a> and update your phone number. You'll be asked to verify the new number with an SMS code. Once verified, all your existing stickers route calls to the new number automatically — you don't need new stickers.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">The NFC tap isn't working — what should I check?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Make sure the phone's NFC is turned on (on iPhone it's always on; on Android check Settings → Connected devices → NFC). Hold the back of the phone <strong>directly</strong> on the sticker for 1–2 seconds. If the tap still doesn't trigger, the QR code on the same sticker is a 100% reliable fallback — just open your camera and point it at the QR.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">I have a referral code — how does it work?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Each TapMyCar account has a referral code (visible in <a href=\"/settings.html\">Settings</a>). Share it with a friend; when they sign up and activate, both of you get a credit applied to your account. Credits reduce future charges automatically at checkout.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">I forgot my password / can't sign in.<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>TapMyCar uses passwordless sign-in. On the <a href=\"/signin.html\">sign-in page</a>, enter your phone number — we'll text you a code to log in. If you can't receive the code, email <a href=\"mailto:support@tapmycar.io\">support@tapmycar.io</a> from the email on your account.</p></div></div>\n\n      <div class=\"help-item\"><div class=\"help-q\">How do I delete my account?<svg class=\"help-q-chev\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></div><div class=\"help-a\"><p>Email <a href=\"mailto:support@tapmycar.io\">support@tapmycar.io</a> from your account email and we'll permanently delete your account, stickers, and call history within 7 days. You can request a copy of your data first if you want.</p></div></div>\n    </div>\n\n  </div>\n\n  <div class=\"help-noresults\" id=\"help-noresults\">\n    No questions match your search. Try a different word, or email us below.\n  </div>\n\n  <div class=\"help-contact\">\n    <div class=\"help-contact-h\">Didn't find what you needed?</div>\n    <div class=\"help-contact-s\">We answer every email, usually within one business day.</div>\n    <a href=\"mailto:support@tapmycar.io\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M4 4h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z\"/><polyline points=\"22 6 12 13 2 6\"/></svg>\n      Email support@tapmycar.io\n    </a>\n  </div>\n\n</div>\n\n<script>\n/* TMC_SMART_BACK: context-aware back navigation. */\nwindow.tmcSmartBack = function (fallback) {\n  fallback = fallback || '/dashboard.html';\n  try {\n    if (document.referrer) {\n      var ref = new URL(document.referrer);\n      if (ref.origin === window.location.origin) {\n        var here = window.location.pathname.replace(/\\/+$/, '');\n        var refPath = ref.pathname.replace(/\\/+$/, '');\n        if (refPath !== here) { window.history.back(); return; }\n      }\n    }\n  } catch (e) {}\n  window.location.href = fallback;\n};\n\n/* FAQ: accordion + search */\n(function () {\n  var items = document.querySelectorAll('.help-item');\n  items.forEach(function (item) {\n    var q = item.querySelector('.help-q');\n    q.addEventListener('click', function () { item.classList.toggle('open'); });\n  });\n\n  var input = document.getElementById('help-q-input');\n  var noResults = document.getElementById('help-noresults');\n  var sections = document.querySelectorAll('.help-section');\n\n  input.addEventListener('input', function () {\n    var q = (input.value || '').trim().toLowerCase();\n    var anyVisible = false;\n    sections.forEach(function (sec) {\n      var sectionHasMatch = false;\n      sec.querySelectorAll('.help-item').forEach(function (item) {\n        var text = item.textContent.toLowerCase();\n        var match = !q || text.indexOf(q) !== -1;\n        item.style.display = match ? '' : 'none';\n        if (match) { sectionHasMatch = true; anyVisible = true; }\n        if (q && match) { item.classList.add('open'); }\n        else if (!q) { item.classList.remove('open'); }\n      });\n      sec.style.display = sectionHasMatch ? '' : 'none';\n    });\n    noResults.classList.toggle('show', q && !anyVisible);\n  });\n})();\n</script>\n</body>\n</html>\n",
  'public/settings.html': "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"TapMyCar\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n<title>Settings — TapMyCar</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n<link rel=\"stylesheet\" href=\"/tmc-redesign.css\">\n<style>\n.edit-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:200;align-items:flex-end;justify-content:center}\n.edit-overlay.show{display:flex}\n.edit-sheet{background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:430px;padding:24px 20px 34px;animation:slideUp .3s ease}\n@keyframes slideUp{from{transform:translateY(100%)}to{transform:translateY(0)}}\n.edit-sheet h3{font-size:16px;font-weight:800;color:#111;margin-bottom:16px}\n.edit-field{margin-bottom:14px}\n.edit-field label{display:block;font-size:11px;font-weight:600;color:#111;margin-bottom:5px}\n.edit-field input{width:100%;height:46px;border:1.5px solid #E5E7EB;border-radius:11px;padding:0 14px;font-size:14px;font-family:'Inter',sans-serif;background:#F9FAFB;outline:none}\n.edit-field input:focus{border-color:#FF6B00}\n</style>\n<!-- Favicon -->\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<!-- SEO -->\n<meta name=\"description\" content=\"Manage your TapMyCar account, plan, referrals, and notifications.\">\n<meta name=\"author\" content=\"Praman Tech LLC\">\n<!-- Open Graph -->\n<meta property=\"og:title\" content=\"Settings — TapMyCar\">\n<meta property=\"og:description\" content=\"Manage your TapMyCar account, plan, referrals, and notifications.\">\n<meta property=\"og:image\" content=\"https://tapmycar.io/og-image.png\">\n<meta property=\"og:url\" content=\"https://tapmycar.io/settings.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"TapMyCar\">\n<!-- Twitter Card -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Settings — TapMyCar\">\n<meta name=\"twitter:description\" content=\"Manage your TapMyCar account, plan, referrals, and notifications.\">\n<meta name=\"twitter:image\" content=\"https://tapmycar.io/og-image.png\">\n</head>\n<body>\n<div class=\"nav\"><div class=\"bk\" onclick=\"history.back()\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Settings</span></div><a href=\"/dashboard.html\" aria-label=\"TapMyCar\" style=\"display:flex;align-items:center;text-decoration:none\"><img src=\"/logo.png\" alt=\"TapMyCar\" class=\"nav-logo-img\" style=\"height:36px;width:auto\"></a></div>\n<div class=\"chev\"></div>\n<div class=\"page\">\n  <!-- Profile header -->\n  <div style=\"padding:20px 20px 14px;text-align:center\">\n    <div style=\"width:68px;height:68px;border-radius:50%;background:var(--or);margin:0 auto 12px;display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:800;color:#fff\" id=\"profile-av\">U</div>\n    <div style=\"font-size:18px;font-weight:800;color:var(--bk);margin-bottom:3px\" id=\"profile-name\">Loading...</div>\n    <div style=\"font-size:12px;color:var(--gy);margin-bottom:4px\" id=\"profile-email\"></div>\n    <div style=\"font-size:12px;color:var(--gy);margin-bottom:10px\" id=\"profile-phone\"></div>\n    <div style=\"display:inline-flex;align-items:center;gap:4px;background:var(--orl);border:.5px solid var(--orl2);border-radius:99px;padding:4px 14px;font-size:11px;font-weight:600;color:var(--or)\" id=\"profile-plan\">Loading...</div>\n  </div>\n\n  <!-- Edit profile -->\n  <div class=\"sl\">Profile</div>\n  <div class=\"set-row\" onclick=\"openEditProfile()\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg></div><div><div class=\"set-t\">Edit profile</div><div class=\"set-s\">Name, phone, email</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Tag -->\n  <div class=\"sl\">Tag</div>\n  <div class=\"set-row\" onclick=\"window.location.href='/etag.html'\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg></div><div><div class=\"set-t\">Manage tag</div><div class=\"set-s\" id=\"tag-info\">View your eTag</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Notifications -->\n  <div class=\"sl\">Notifications</div>\n  <div class=\"set-row\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><path d=\"M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9\"/><path d=\"M13.73 21a2 2 0 0 1-3.46 0\"/></svg></div><div><div class=\"set-t\">SMS alerts</div><div class=\"set-s\">When tag is scanned</div></div></div><button class=\"tog on\" id=\"sms-tog\" onclick=\"toggleSMS()\"><div class=\"tog-d\"></div></button></div>\n\n  <!-- Plan -->\n  <div class=\"sl\">Plan & billing</div>\n  <!-- TMC_PATCH36C_BILLING: Manage plan -> Plan & Billing -->\n  <div class=\"set-row\" onclick=\"window.location.href='/billing.html'\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><rect x=\"1\" y=\"4\" width=\"22\" height=\"16\" rx=\"2\"/><line x1=\"1\" y1=\"10\" x2=\"23\" y2=\"10\"/></svg></div><div><div class=\"set-t\">Plan & Billing</div><div class=\"set-s\" id=\"plan-info\">Plan, renewal & payments</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- App -->\n  <div class=\"sl\">App</div>\n  <div class=\"set-row\" onclick=\"window.location.href='/landing.html'\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div><div><div class=\"set-t\">About TapMyCar</div><div class=\"set-s\">Privacy for you. Safety for your car.</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n  <div class=\"set-row\" onclick=\"openReviewModal()\" id=\"leave-review-row\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg></div><div><div class=\"set-t\">Leave a review</div><div class=\"set-s\">Share your experience with TapMyCar</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n  <div class=\"set-row\" onclick=\"window.location.href='/reviews.html'\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><path d=\"M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z\"/></svg></div><div><div class=\"set-t\">All reviews</div><div class=\"set-s\">See what others say</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Legal -->\n  <div class=\"sl\">Legal</div>\n  <div class=\"set-row\" onclick=\"window.location.href='/privacy.html'\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div><div><div class=\"set-t\">Privacy Policy</div><div class=\"set-s\">How we handle your data</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n  <div class=\"set-row\" onclick=\"window.location.href='/terms.html'\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></div><div><div class=\"set-t\">Terms of Service</div><div class=\"set-s\">Rules for using TapMyCar</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Support -->\n  <div class=\"sl\">Support</div>\n  <div class=\"set-row\" onclick=\"window.location.href='/help.html'\"><!-- TMC_HELP_PAGE --><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--orl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></div><div><div class=\"set-t\">Help & FAQ</div><div class=\"set-s\">Common questions, billing, privacy</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Referrals -->\n  <div class=\"sl\">Referrals</div>\n  <div class=\"card\" style=\"margin:0 16px 8px;padding:16px\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:12px\">\n      <div><div style=\"font-size:13px;font-weight:700;color:#111\">Your referral code</div><div style=\"font-size:20px;font-weight:800;color:var(--or);letter-spacing:1px;margin-top:2px\" id=\"ref-code\">Loading...</div></div>\n      <button onclick=\"shareRefLink()\" style=\"background:var(--or);color:#fff;border:none;border-radius:11px;padding:8px 16px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit\">Share Link</button>\n    </div>\n    <input type=\"text\" id=\"ref-link\" readonly onclick=\"copyRefLink()\" style=\"width:100%;height:40px;border:1.5px solid #E5E7EB;border-radius:11px;padding:0 12px;font-size:11px;color:#6B7280;background:#F9FAFB;cursor:pointer;font-family:inherit;box-sizing:border-box\" placeholder=\"Loading...\">\n    <!-- TMC_PATCH45A_FIX: integrated progress strip, no nested boxes -->\n    <div style=\"margin-top:18px;padding:14px 4px 0;border-top:1px solid #F3F4F6;display:flex;align-items:stretch\">\n      <div style=\"flex:1;text-align:center\">\n        <div style=\"font-size:22px;font-weight:800;color:#111;line-height:1\" id=\"ref-signups\">0</div>\n        <div style=\"font-size:10px;color:#9CA3AF;margin-top:6px;font-weight:600;letter-spacing:0.03em\">SIGNED UP</div>\n      </div>\n      <div style=\"width:1px;background:#F3F4F6;margin:2px 0\"></div>\n      <div style=\"flex:1;text-align:center\">\n        <div style=\"font-size:22px;font-weight:800;color:#111;line-height:1\" id=\"ref-confirmed\">0</div>\n        <div style=\"font-size:10px;color:#9CA3AF;margin-top:6px;font-weight:600;letter-spacing:0.03em\">PAID</div>\n      </div>\n      <div style=\"width:1px;background:#F3F4F6;margin:2px 0\"></div>\n      <div style=\"flex:1;text-align:center\">\n        <div style=\"font-size:22px;font-weight:800;color:#16A34A;line-height:1\" id=\"ref-available\">$0</div>\n        <div style=\"font-size:10px;color:#9CA3AF;margin-top:6px;font-weight:600;letter-spacing:0.03em\">AVAILABLE</div>\n      </div>\n      <div style=\"width:1px;background:#F3F4F6;margin:2px 0\"></div>\n      <div style=\"flex:1;text-align:center\">\n        <div style=\"font-size:22px;font-weight:800;color:#FF6B00;line-height:1\" id=\"ref-pending\">$0</div>\n        <div style=\"font-size:10px;color:#9CA3AF;margin-top:6px;font-weight:600;letter-spacing:0.03em\">PENDING</div>\n      </div>\n    </div>\n    <div id=\"ref-next\" style=\"margin-top:14px;font-size:12px;color:#6B7280;line-height:1.5\">Loading...</div>\n    <div id=\"ref-reward-box\" style=\"display:none;background:#DCFCE7;border:1.5px solid #BBF7D0;border-radius:10px;padding:12px;margin-top:12px\">\n      <div style=\"font-size:12px;font-weight:700;color:#166534;margin-bottom:8px\">You earned a reward! Choose one:</div>\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:8px\">\n        <button id=\"claim-free_standard\" onclick=\"claimReward('free_standard')\" style=\"background:#16A34A;color:#fff;border:none;border-radius:10px;padding:10px 6px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit\">Free Standard Plan</button>\n        <button id=\"claim-coupon\" onclick=\"claimReward('coupon')\" style=\"background:#FF6B00;color:#fff;border:none;border-radius:10px;padding:10px 6px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit\">$4.99 Coupon</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- Cancel Subscription (only shown if user has an active subscription) -->\n  <div class=\"set-row\" id=\"cancel-sub-row\" style=\"display:none\" onclick=\"cancelSubscription()\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:#FFF3EC\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--or)\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\"/></svg></div><div><div class=\"set-t\">Cancel subscription</div><div class=\"set-s\">Stop future charges. Keeps tag active until paid period ends.</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Danger zone -->\n  <div class=\"sl\" style=\"color:var(--rd)\">Danger zone</div>\n  <div class=\"set-row\" onclick=\"deleteAccount()\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--rdl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--rd)\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/></svg></div><div><div class=\"set-t\" style=\"color:var(--rd)\">Delete account</div><div class=\"set-s\">Permanently delete your account and all data.</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <!-- Sign out -->\n  <div class=\"set-row\" onclick=\"signOut()\"><div class=\"set-l\"><div class=\"set-ic\" style=\"background:var(--rdl)\"><svg viewBox=\"0 0 24 24\" stroke=\"var(--rd)\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg></div><div><div class=\"set-t\" style=\"color:var(--rd)\">Sign out</div></div></div><div class=\"arr\"><svg viewBox=\"0 0 24 24\"><polyline points=\"9 18 15 12 9 6\"/></svg></div></div>\n\n  <div style=\"padding:20px;text-align:center\"><div style=\"font-size:11px;color:#CCC\">TapMyCar v1.0.0  Praman Tech LLC  Connecticut</div></div>\n</div>\n\n<!-- Edit Profile Sheet -->\n<div class=\"edit-overlay\" id=\"edit-overlay\" onclick=\"if(event.target===this)closeEdit()\">\n  <div class=\"edit-sheet\">\n    <h3>Edit Profile</h3>\n    <div class=\"edit-field\">\n      <label>Full name</label>\n      <input type=\"text\" id=\"edit-name\" placeholder=\"Your name\">\n    </div>\n    <div class=\"edit-field\">\n      <label>Phone number</label>\n      <div style=\"display:flex;gap:8px;align-items:stretch\">\n      <select id=\"edit-country-code\" style=\"height:46px;border:1.5px solid #E5E7EB;border-radius:11px;padding:0 10px;font-size:14px;font-family:'Inter',sans-serif;background:#F9FAFB;outline:none;color:#111;min-width:90px\">\n                <option value=\"+1\">US +1</option>\n        <option value=\"+44\">UK +44</option>\n        <option value=\"+91\">IN +91</option>\n        <option value=\"+61\">AU +61</option>\n        <option value=\"+1-CA\">CA +1</option>\n        <option value=\"+49\">DE +49</option>\n        <option value=\"+33\">FR +33</option>\n        <option value=\"+39\">IT +39</option>\n        <option value=\"+34\">ES +34</option>\n        <option value=\"+55\">BR +55</option>\n        <option value=\"+52\">MX +52</option>\n        <option value=\"+971\">AE +971</option>\n        <option value=\"+65\">SG +65</option>\n        <option value=\"+81\">JP +81</option>\n        <option value=\"+82\">KR +82</option>\n        <option value=\"+86\">CN +86</option>\n      </select>\n      <input type=\"tel\" id=\"edit-phone\" placeholder=\"(203) 555-0100\" style=\"flex:1;height:46px;border:1.5px solid #E5E7EB;border-radius:11px;padding:0 14px;font-size:14px;font-family:'Inter',sans-serif;background:#F9FAFB;outline:none\">\n    </div>\n    </div>\n    <div class=\"edit-field\">\n      <label>Email address</label>\n      <input type=\"email\" id=\"edit-email\" placeholder=\"jane@example.com\">\n    </div>\n    <div style=\"height:1px;background:#F3F4F6;margin:4px 0 12px\"></div>\n    <div style=\"font-size:11px;font-weight:700;color:#6B7280;margin-bottom:10px;text-transform:uppercase;letter-spacing:.05em\">Emergency Contact (optional)</div>\n    <div class=\"edit-field\">\n      <label>Contact name</label>\n      <input type=\"text\" id=\"edit-emergency-name\" placeholder=\"e.g. John Smith\">\n    </div>\n    <div class=\"edit-field\">\n      <label>Contact phone</label>\n      <input type=\"tel\" id=\"edit-emergency-phone\" placeholder=\"+1 (203) 555-0100\">\n      <div style=\"font-size:10px;color:#9CA3AF;margin-top:4px\">Notified if you don't respond to a scan alert</div>\n    </div>\n    <!-- TMC_WELCOME_MSG_UI -->\n    <div style=\"height:1px;background:#F3F4F6;margin:12px 0\"></div>\n    <div style=\"font-size:11px;font-weight:700;color:#6B7280;margin-bottom:10px;text-transform:uppercase;letter-spacing:.05em\">Note shown to strangers (optional)</div>\n    <div class=\"edit-field\">\n      <label>A short message that appears when someone scans your tag</label>\n      <textarea id=\"edit-welcome-message\" maxlength=\"120\" rows=\"3\" placeholder=\"e.g. If my lights are on please tap that — I respond fast.\" style=\"width:100%;border:1.5px solid #E5E7EB;border-radius:10px;padding:10px 12px;font-size:13px;font-family:inherit;resize:none;color:#111\"></textarea>\n      <div style=\"font-size:10px;color:#9CA3AF;margin-top:4px\">Max 120 chars. Phone numbers and email addresses are auto-removed for privacy.</div>\n    </div>\n    <button class=\"btn\" onclick=\"saveProfile()\" id=\"save-btn\">Save changes</button>\n    <button class=\"btn-o\" style=\"margin-top:8px\" onclick=\"closeEdit()\">Cancel</button>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"><div class=\"toast-ic\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><span id=\"toast-msg\"></span></div>\n\n<script src=\"/app.js\"></script>\n<script>\nrequireAuth();\nconst s = getSession();\nlet userData = null;\nlet tagData = null;\n\nasync function loadSettings() {\n  try {\n    const res = await fetch('/api/get-dashboard?user_id=' + s.token);\n    const data = await res.json();\n    if (data.user) {\n      userData = data.user;\n      document.getElementById('profile-name').textContent = data.user.name || 'User';\n      document.getElementById('profile-av').textContent = (data.user.name || 'U')[0].toUpperCase();\n      document.getElementById('profile-phone').textContent = data.user.phone || '';\n      document.getElementById('profile-email').textContent = data.user.email || '';\n      const plan = data.user.plan || 'etag';\n      const planNames = { etag: 'eTag (Free)', standard: 'Standard', premium: 'Premium', business: 'Business' };\n      if (data.user.subscription_id) { document.getElementById('cancel-sub-row').style.display = 'flex'; }\n      document.getElementById('profile-plan').textContent = ' ' + (planNames[plan] || plan);\n      document.getElementById('plan-info').textContent = (planNames[plan] || plan) + ' plan';\n    }\n    if (data.tags && data.tags.length > 0) {\n      tagData = data.tags[0];\n      document.getElementById('tag-info').textContent = (tagData.token.includes('-') ? tagData.token : 'TMC-' + tagData.token.replace(/^TMC[-.]?/,'')) + ' - ' + (tagData.status || 'unknown');\n    }\n  } catch(e) { console.error('Settings load error:', e); }\n}\n\n/* TMC_PATCH30_PHONE_SPLIT: split stored E.164 phone into country-code + local number */\nfunction _p30SplitPhone(stored) {\n  var s = (stored == null ? '' : String(stored)).trim();\n  if (!s) return { cc: '+1', local: '' };\n  /* Build a list of dropdown option values, sorted by length (descending)\n     so longer prefixes match first (\"+971\" before \"+9\", \"+44\" before \"+1\"). */\n  var sel = document.getElementById('edit-country-code');\n  var values = [];\n  if (sel && sel.options) {\n    for (var i = 0; i < sel.options.length; i++) {\n      var v = sel.options[i].value;\n      if (v) values.push(v);\n    }\n  }\n  values.sort(function(a, b) {\n    /* Compare by the \"+digits\" part length, ignoring suffixes like \"-CA\" */\n    var na = a.replace(/-.*$/, '').length;\n    var nb = b.replace(/-.*$/, '').length;\n    return nb - na;\n  });\n  for (var j = 0; j < values.length; j++) {\n    var cc = values[j].replace(/-.*$/, ''); /* \"+1-CA\" -> \"+1\" for matching */\n    if (s.indexOf(cc) === 0) {\n      return { cc: values[j], local: s.slice(cc.length) };\n    }\n  }\n  /* Stored doesn't start with any known cc -> treat as local-only US number. */\n  if (s.charAt(0) === '+') {\n    /* Has a + but unknown country. Keep as local for display. */\n    return { cc: '+1', local: s };\n  }\n  return { cc: '+1', local: s };\n}\n\nfunction openEditProfile() {\n  if (userData) {\n    document.getElementById('edit-name').value = userData.name || '';\n    /* TMC_PATCH30_PHONE_SPLIT: split phone into dropdown + input */\n    var _p30 = _p30SplitPhone(userData.phone);\n    var _ccSel = document.getElementById('edit-country-code');\n    if (_ccSel) {\n      /* Try exact match first; if a country-specific variant like \"+1-CA\"\n         exists in stored data, prefer it. Otherwise fall back to plain cc. */\n      var found = false;\n      for (var i = 0; i < _ccSel.options.length; i++) {\n        if (_ccSel.options[i].value === _p30.cc) { _ccSel.value = _p30.cc; found = true; break; }\n      }\n      if (!found) _ccSel.value = '+1';\n    }\n    document.getElementById('edit-phone').value = _p30.local;\n    document.getElementById('edit-email').value = userData.email || '';\n    document.getElementById('edit-emergency-name').value = userData.emergency_name || '';\n    document.getElementById('edit-emergency-phone').value = userData.emergency_contact || '';\n    document.getElementById('edit-welcome-message').value = userData.welcome_message || '';\n  }\n  document.getElementById('edit-overlay').classList.add('show');\n}\n\nfunction closeEdit() { document.getElementById('edit-overlay').classList.remove('show'); }\n\nasync function saveProfile() {\n  const name = document.getElementById('edit-name').value.trim();\n  const editCC = document.getElementById('edit-country-code').value.replace('-CA',''); const phoneRaw = document.getElementById('edit-phone').value.trim().replace(/[^0-9]/g,''); const phone = phoneRaw ? editCC + phoneRaw : '';\n  const email = document.getElementById('edit-email').value.trim();\n  const emergencyName = document.getElementById('edit-emergency-name').value.trim();\n  const emergencyPhone = document.getElementById('edit-emergency-phone').value.trim();\n  const welcomeMessage = document.getElementById('edit-welcome-message').value.trim();\n  if (!name) { showToast('Name is required'); return; }\n  const btn = document.getElementById('save-btn');\n  btn.textContent = 'Saving...'; btn.disabled = true;\n  try {\n    const res = await fetch('/api/get-dashboard', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ user_id: s.token, name, phone, email, emergency_name: emergencyName, emergency_contact: emergencyPhone, welcome_message: welcomeMessage }) });\n    const data = await res.json();\n    if (data.success) {\n      localStorage.setItem('tmc_name', name); localStorage.setItem('tmc_phone', phone); localStorage.setItem('tmc_email', email);\n      document.getElementById('profile-name').textContent = name;\n      document.getElementById('profile-av').textContent = name[0].toUpperCase();\n      document.getElementById('profile-phone').textContent = phone || '';\n      document.getElementById('profile-email').textContent = email || '';\n      closeEdit(); showToast('Profile updated!');\n    } else { showToast(data.error || 'Failed to save'); }\n  } catch(e) { showToast('Network error'); }\n  btn.textContent = 'Save changes'; btn.disabled = false;\n}\n\nfunction toggleSMS() {\n  const tog = document.getElementById('sms-tog');\n  tog.classList.toggle('on');\n  showToast(tog.classList.contains('on') ? 'SMS alerts enabled' : 'SMS alerts disabled');\n}\n\n/* TMC_PATCH31_REFUND: refund-aware cancel (fixed in TMC_PATCH32_REFUND_FIX) */\nlet _p31Elig = null;\n\nasync function _p31LoadEligibility() {\n  try {\n    const r = await fetch('/api/cancel-subscription-preview?user_id=' + encodeURIComponent(s.token));\n    if (!r.ok) return null;\n    const data = await r.json();\n    if (!data || !data.success) return null;\n    _p31Elig = data;\n    const sub = document.querySelector('#cancel-sub-row .set-s');\n    if (sub && data.eligible && data.refund_cents > 0) {\n      const dollars = (data.refund_cents / 100).toFixed(2);\n      sub.textContent = 'Refund $' + dollars + ' available (within 14 days)';\n    }\n    return data;\n  } catch (e) { return null; }\n}\n\nasync function cancelSubscription() {\n  await _p31LoadEligibility();\n\n  let confirmed = false;\n  if (_p31Elig && _p31Elig.eligible && _p31Elig.refund_cents > 0) {\n    const dollars = (_p31Elig.refund_cents / 100).toFixed(2);\n    confirmed = confirm(\n      'Cancel and refund $' + dollars + '?\\n\\n' +\n      'You paid your annual subscription within the last 14 days, so we will refund $' + dollars + ' to your card now.\\n' +\n      '($1 service fee retained per refund policy.)\\n\\n' +\n      'After the refund:\\n' +\n      '• Your subscription stops immediately\\n' +\n      '• Your tag becomes inactive\\n' +\n      '• Physical stickers you have are yours to keep\\n' +\n      '• You can re-subscribe anytime\\n\\n' +\n      'Refund arrives in 3-5 business days.'\n    );\n  } else {\n    confirmed = confirm(\n      'Cancel your TapMyCar subscription?\\n\\n' +\n      'You will not be charged again. Your tag stays active until the end of your current paid period.\\n\\n' +\n      'Physical stickers already shipped are yours to keep.\\n\\n' +\n      'Note: refunds are only available within 14 days of an annual charge.'\n    );\n  }\n  if (!confirmed) return;\n\n  try {\n    const res = await fetch('/api/cancel-subscription', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({ user_id: s.token })\n    });\n    const data = await res.json();\n    if (data.success) {\n      if (data.refund_issued && data.refund_amount_cents > 0) {\n        const d = (data.refund_amount_cents / 100).toFixed(2);\n        showToast('Canceled. Refund of $' + d + ' on its way.');\n      } else {\n        showToast('Subscription canceled');\n      }\n      document.getElementById('cancel-sub-row').style.display = 'none';\n    } else {\n      showToast(data.error || 'Failed to cancel');\n    }\n  } catch(e) {\n    showToast('Network error');\n  }\n}\n\n/* TMC_PATCH32_REFUND_FIX: load eligibility shortly after page mount */\n(function() {\n  function _kick() { try { _p31LoadEligibility(); } catch(e) {} }\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function() { setTimeout(_kick, 800); });\n  } else {\n    setTimeout(_kick, 800);\n  }\n})();\n\n/* TMC_PATCH42_PREDELETE: replaces the two-step confirm/prompt flow with a\n   single custom modal that also captures exit reason + email consent.\n   The existing /api/delete-account contract is preserved (still passes\n   confirm:'DELETE'); the three new fields are added alongside. */\nfunction deleteAccount() {\n  /* lazy-build the modal so settings.html doesn't carry its DOM until needed */\n  var existing = document.getElementById('tmc-predelete-modal');\n  if (existing) { existing.style.display = 'flex'; return; }\n\n  var ov = document.createElement('div');\n  ov.id = 'tmc-predelete-modal';\n  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px;font-family:Inter,system-ui,sans-serif';\n  ov.innerHTML =\n    '<div style=\"background:#fff;max-width:440px;width:100%;border-radius:16px;padding:22px;max-height:92vh;overflow-y:auto\">' +\n      '<div style=\"font-size:18px;font-weight:800;color:#111;margin-bottom:6px\">Before you go</div>' +\n      '<div style=\"font-size:13px;color:#6B7280;line-height:1.55;margin-bottom:18px\">Deleting your account cancels any active subscription, disables your tags, and permanently removes your personal data. This cannot be undone.</div>' +\n      '<div style=\"font-size:13px;font-weight:700;color:#111;margin-bottom:8px\">Why are you leaving?</div>' +\n      '<div id=\"tmc-pd-reasons\" style=\"display:flex;flex-direction:column;gap:6px;margin-bottom:12px\">' +\n        reasonRow('too_expensive',     'It\\'s too expensive') +\n        reasonRow('no_longer_need',    'I no longer need it') +\n        reasonRow('not_as_expected',   'It didn\\'t work as I expected') +\n        reasonRow('privacy_concerns',  'Privacy concerns') +\n        reasonRow('found_alternative', 'I found an alternative') +\n        reasonRow('other',             'Other') +\n      '</div>' +\n      '<textarea id=\"tmc-pd-text\" placeholder=\"Anything else you\\'d like us to know? (optional)\" style=\"width:100%;box-sizing:border-box;min-height:60px;padding:10px;border:1.5px solid #E5E7EB;border-radius:10px;font-size:13px;font-family:inherit;resize:vertical;margin-bottom:14px\"></textarea>' +\n      '<label style=\"display:flex;align-items:flex-start;gap:8px;padding:10px;border:1.5px solid #E5E7EB;border-radius:10px;margin-bottom:14px;cursor:pointer\">' +\n        '<input type=\"checkbox\" id=\"tmc-pd-consent\" style=\"margin-top:2px;flex-shrink:0\">' +\n        '<span style=\"font-size:12px;color:#374151;line-height:1.5\">It\\'s OK to email me about future offers and updates from TapMyCar.</span>' +\n      '</label>' +\n      '<div id=\"tmc-pd-err\" style=\"font-size:12px;color:#DC2626;min-height:18px;margin-bottom:8px\"></div>' +\n      '<div style=\"display:flex;gap:10px\">' +\n        '<button type=\"button\" onclick=\"closePreDelete()\" style=\"flex:1;padding:12px;border:1.5px solid #E5E7EB;background:#fff;border-radius:10px;font-weight:700;font-size:13px;color:#111;cursor:pointer\">Cancel</button>' +\n        '<button type=\"button\" id=\"tmc-pd-go\" onclick=\"submitPreDelete()\" style=\"flex:1;padding:12px;background:#DC2626;color:#fff;border:0;border-radius:10px;font-weight:700;font-size:13px;cursor:pointer\">Permanently delete</button>' +\n      '</div>' +\n    '</div>';\n  document.body.appendChild(ov);\n  function reasonRow(code, label) {\n    return '<label style=\"display:flex;align-items:center;gap:8px;padding:8px 10px;border:1.5px solid #E5E7EB;border-radius:8px;cursor:pointer\">' +\n      '<input type=\"radio\" name=\"tmc-pd-reason\" value=\"' + code + '\" style=\"flex-shrink:0\">' +\n      '<span style=\"font-size:13px;color:#111\">' + label + '</span></label>';\n  }\n}\n\n/* TMC_PATCH51B: pre-delete retention offer (step 2) */\nfunction showRetentionOffer() {\n  /* Hide step-1 contents, show step-2 inside the SAME modal. */\n  var modal = document.getElementById('tmc-predelete-modal');\n  if (!modal) return;\n  var card = modal.querySelector('div');\n  if (!card) return;\n  card.innerHTML = '' +\n    '<div style=\"text-align:center;margin-bottom:14px\">' +\n      '<div style=\"font-size:32px;margin-bottom:4px\">\\uD83C\\uDF81</div>' +\n      '<div style=\"font-size:18px;font-weight:800;color:#111\">Wait \\u2014 here\\'s $3 off your next renewal</div>' +\n    '</div>' +\n    '<div style=\"font-size:13px;color:#6B7280;line-height:1.6;margin-bottom:16px;text-align:center\">As a thank-you for trying TapMyCar, we\\'d like to credit your account with $3 toward your next annual subscription renewal. Your tag stays active, no charge today.</div>' +\n    '<div style=\"background:#F0FDF4;border:1px solid #BBF7D0;border-radius:12px;padding:12px;margin-bottom:14px;font-size:12px;color:#15803D;text-align:center\">' +\n      '<b>$3.00 credit</b>  applies automatically at your next annual renewal' +\n    '</div>' +\n    '<div id=\"tmc-ret-err\" style=\"font-size:12px;color:#DC2626;min-height:18px;margin-bottom:6px;text-align:center\"></div>' +\n    '<div style=\"display:flex;flex-direction:column;gap:8px\">' +\n      '<button type=\"button\" id=\"tmc-ret-accept\" onclick=\"acceptRetentionOffer()\" style=\"width:100%;padding:13px;background:#FF6B00;color:#fff;border:0;border-radius:11px;font-weight:700;font-size:14px;cursor:pointer\">Yes, keep my account</button>' +\n      '<button type=\"button\" id=\"tmc-ret-decline\" onclick=\"declineRetentionOffer()\" style=\"width:100%;padding:11px;background:transparent;color:#6B7280;border:0;font-weight:600;font-size:13px;cursor:pointer\">No thanks, delete my account</button>' +\n    '</div>';\n}\n\nasync function acceptRetentionOffer() {\n  var btn = document.getElementById('tmc-ret-accept');\n  var dec = document.getElementById('tmc-ret-decline');\n  var err = document.getElementById('tmc-ret-err');\n  if (btn) { btn.disabled = true; btn.textContent = 'Applying \\u2026'; }\n  if (dec) dec.disabled = true;\n  if (err) err.textContent = '';\n  try {\n    var res = await fetch('/api/grant-retention-credit', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ exit_reason: __tmcPreDeleteState && __tmcPreDeleteState.reasonCode })\n    });\n    var data = await res.json();\n    if (data && data.ok) {\n      closePreDelete();\n      showToast('$3 credit added to your account for next renewal!');\n      /* Refresh referrals card so the user sees something happened. */\n      try { if (typeof loadReferrals === 'function') loadReferrals(); } catch (e) {}\n      return;\n    }\n    /* TMC_PATCH51B_FIX: if already_shown comes back, the server has the\n       lock set but somehow the modal slipped through. Close it and proceed\n       to delete  the user's actual intent. No nonsensical red text. */\n    if (data && data.reason === 'already_shown') {\n      closePreDelete();\n      /* Proceed to delete using cached pre-delete answers. */\n      if (typeof declineRetentionOffer === 'function') {\n        declineRetentionOffer();\n      }\n      return;\n    }\n    throw new Error((data && data.error) || 'Could not apply credit');\n  } catch (e) {\n    if (err) err.textContent = 'Something went wrong applying the credit. Try again or contact support@tapmycar.io';\n    if (btn) { btn.disabled = false; btn.textContent = 'Yes, keep my account'; }\n    if (dec) dec.disabled = false;\n  }\n}\n\nasync function declineRetentionOffer() {\n  var st = __tmcPreDeleteState || { reasonCode: '', reasonText: '', consent: false };\n  /* Consume the one-time gate so they can\\'t come back and farm it. */\n  try {\n    await fetch('/api/decline-retention-offer', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ exit_reason: st.reasonCode })\n    });\n  } catch (e) { /* non-fatal */ }\n\n  /* TMC_PATCH52: capture email/name now, before the delete wipes them. */\n  try {\n    var __tmcTok = s.token || localStorage.getItem('tmc_session_token') || localStorage.getItem('tmc_token');\n    var meRes = await fetch('/api/get-dashboard', { headers: { 'Authorization': 'Bearer ' + __tmcTok } });\n    if (meRes.ok) {\n      var meData = await meRes.json();\n      window.__tmcDelEmail = (meData && meData.user && meData.user.email) || '';\n      window.__tmcDelName  = (meData && meData.user && meData.user.name)  || '';\n    }\n  } catch (e) { /* non-fatal  signup screen will just have blank fields */ }\n\n  /* Now actually proceed with the delete. We rebuild the spinner state\n     inside the modal so the user sees something is happening. */\n  var modal = document.getElementById('tmc-predelete-modal');\n  if (modal) {\n    var card = modal.querySelector('div');\n    if (card) card.innerHTML = '<div style=\"padding:30px;text-align:center;font-size:14px;color:#6B7280\">Deleting your account\\u2026</div>';\n  }\n  try {\n    var res = await fetch('/api/delete-account', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        user_id: s.token,\n        confirm: 'DELETE',\n        exit_reason_code: st.reasonCode,\n        exit_reason_text: st.reasonText,\n        marketing_consent: !!st.consent\n      })\n    });\n    var data = await res.json();\n    if (data && data.success) {\n      /* TMC_PATCH52: show post-delete newsletter signup screen instead of\n         immediately redirecting. Captured email comes from window.__tmcDelEmail\n         and window.__tmcDelName which we set just before calling delete. */\n      try { localStorage.clear(); } catch (e) {}\n      showPostDeleteSignup(\n        window.__tmcDelEmail || '',\n        window.__tmcDelName  || '',\n        (st && st.reasonCode) || ''\n      );\n    } else {\n      closePreDelete();\n      alert((data && data.error) || 'Failed to delete. Please contact support@tapmycar.io.');\n    }\n  } catch (e) {\n    closePreDelete();\n    alert('Network error \\u2014 please try again.');\n  }\n}\n\n/* TMC_PATCH52: post-delete newsletter signup screen.\n   Replaces the modal contents (account is already deleted at this point).\n   Subscribe POSTs to /api/newsletter-subscribe; Skip just redirects. */\nfunction showPostDeleteSignup(email, name, exitReason) {\n  var modal = document.getElementById('tmc-predelete-modal');\n  if (!modal) { window.location.href = '/landing.html'; return; }\n  var card = modal.querySelector('div');\n  if (!card) { window.location.href = '/landing.html'; return; }\n  var emailEsc = (email || '').replace(/\"/g, '&quot;');\n  card.innerHTML = '' +\n    '<div style=\"text-align:center;margin-bottom:14px\">' +\n      '<div style=\"font-size:28px;margin-bottom:6px\">\\uD83D\\uDC4B</div>' +\n      '<div style=\"font-size:18px;font-weight:800;color:#111\">Account deleted. Goodbye!</div>' +\n    '</div>' +\n    '<div style=\"font-size:13px;color:#6B7280;line-height:1.6;margin-bottom:16px;text-align:center\">Want to hear from us when we launch new features? Stay on a low-touch newsletter \\u2014 no spam, easy unsubscribe.</div>' +\n    '<input type=\"email\" id=\"tmc-pd-news-email\" value=\"' + emailEsc + '\" placeholder=\"you@example.com\" style=\"width:100%;box-sizing:border-box;padding:12px;font-size:14px;border:1.5px solid #E5E7EB;border-radius:10px;margin-bottom:10px\">' +\n    '<div id=\"tmc-pd-news-err\" style=\"font-size:12px;color:#DC2626;min-height:18px;margin-bottom:6px;text-align:center\"></div>' +\n    '<div style=\"display:flex;flex-direction:column;gap:8px\">' +\n      '<button type=\"button\" id=\"tmc-pd-news-sub\" onclick=\"submitNewsletterSignup(' + JSON.stringify(exitReason || '') + ', ' + JSON.stringify(name || '') + ')\" style=\"width:100%;padding:13px;background:#FF6B00;color:#fff;border:0;border-radius:11px;font-weight:700;font-size:14px;cursor:pointer\">Subscribe to newsletter</button>' +\n      '<button type=\"button\" onclick=\"window.location.href=&quot;/landing.html&quot;\" style=\"width:100%;padding:11px;background:transparent;color:#6B7280;border:0;font-weight:600;font-size:13px;cursor:pointer\">Skip, take me to the homepage</button>' +\n    '</div>';\n}\n\nasync function submitNewsletterSignup(exitReason, name) {\n  var emailEl = document.getElementById('tmc-pd-news-email');\n  var btn = document.getElementById('tmc-pd-news-sub');\n  var err = document.getElementById('tmc-pd-news-err');\n  var email = (emailEl && emailEl.value || '').trim();\n  if (err) err.textContent = '';\n  if (!email || !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) {\n    if (err) err.textContent = 'Please enter a valid email.';\n    return;\n  }\n  if (btn) { btn.disabled = true; btn.textContent = 'Subscribing\\u2026'; }\n  try {\n    var res = await fetch('/api/newsletter-subscribe', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ email: email, name: name || '', exit_reason: exitReason || '' })\n    });\n    var data = await res.json();\n    if (data && data.ok) {\n      window.location.href = '/landing.html?subscribed=1';\n      return;\n    }\n    if (err) err.textContent = (data && data.error) || 'Could not subscribe. Try again.';\n    if (btn) { btn.disabled = false; btn.textContent = 'Subscribe to newsletter'; }\n  } catch (e) {\n    if (err) err.textContent = 'Network error. Try again.';\n    if (btn) { btn.disabled = false; btn.textContent = 'Subscribe to newsletter'; }\n  }\n}\n\nfunction closePreDelete() {\n  var m = document.getElementById('tmc-predelete-modal');\n  if (m) m.remove();\n}\n\n/* TMC_PATCH51B: cache the user's step-1 answers so we can use them after\n   the retention offer step resolves. */\nvar __tmcPreDeleteState = null;\n\nasync function submitPreDelete() {\n  var radio = document.querySelector('input[name=\"tmc-pd-reason\"]:checked');\n  var err = document.getElementById('tmc-pd-err');\n  if (!radio) { err.textContent = 'Please choose a reason.'; return; }\n  var reasonCode = radio.value;\n  var reasonText = (document.getElementById('tmc-pd-text').value || '').trim().slice(0, 1000);\n  var consent    = !!document.getElementById('tmc-pd-consent').checked;\n  var go = document.getElementById('tmc-pd-go');\n\n  /* TMC_PATCH51B_FIX: probe whether the user has already been shown the\n     retention offer. ONLY show the offer modal if we got a clean 200 AND\n     retention_offer_shown_at is null. Any error or non-null  fall through\n     to delete (the user's actual intent). Send auth header explicitly  the\n     original Patch 51b code omitted it, which silently 401'd and caused\n     the offer modal to show even for users who had already accepted. */\n  try {\n    var __tmcTok = s.token || localStorage.getItem('tmc_session_token') || localStorage.getItem('tmc_token');\n    var probe = await fetch('/api/get-dashboard', {\n      headers: { 'Authorization': 'Bearer ' + __tmcTok }\n    });\n    if (probe.ok) {\n      var probeData = await probe.json();\n      /* TMC_PATCH52_FIX2: while we're already here, capture email/name\n         for the post-delete newsletter screen. This is the EARLIEST point\n         where we know the user object is fresh from DB. */\n      try {\n        window.__tmcDelEmail = (probeData && probeData.user && probeData.user.email) || window.__tmcDelEmail || '';\n        window.__tmcDelName  = (probeData && probeData.user && probeData.user.name)  || window.__tmcDelName  || '';\n      } catch (e) {}\n      var alreadyShown = probeData && probeData.user && probeData.user.retention_offer_shown_at;\n      if (!alreadyShown) {\n        __tmcPreDeleteState = { reasonCode: reasonCode, reasonText: reasonText, consent: consent };\n        showRetentionOffer();\n        return;\n      }\n      /* alreadyShown is truthy  user has used the offer before, proceed to delete. */\n    }\n    /* If probe failed or returned non-OK, also proceed to delete. The user\n       clicked Delete; respect that rather than show an offer we cannot\n       verify they are eligible for. */\n  } catch (e) { /* network error  fall through to delete */ }\n\n  go.disabled = true; go.textContent = 'Deleting…'; err.textContent = '';\n\n  /* TMC_PATCH52_FIX: capture email/name now so the post-delete newsletter\n     signup screen can pre-fill them. We already have s.token; just fetch\n     /api/get-dashboard one more time before the row is wiped. */\n  try {\n    var __tmcTok2 = s.token || localStorage.getItem('tmc_session_token') || localStorage.getItem('tmc_token');\n    var meRes2 = await fetch('/api/get-dashboard', { headers: { 'Authorization': 'Bearer ' + __tmcTok2 } });\n    if (meRes2.ok) {\n      var meData2 = await meRes2.json();\n      window.__tmcDelEmail = (meData2 && meData2.user && meData2.user.email) || '';\n      window.__tmcDelName  = (meData2 && meData2.user && meData2.user.name)  || '';\n    }\n  } catch (e) { /* non-fatal */ }\n\n  try {\n    var res = await fetch('/api/delete-account', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        user_id: s.token,\n        confirm: 'DELETE',\n        exit_reason_code: reasonCode,\n        exit_reason_text: reasonText,\n        marketing_consent: consent\n      })\n    });\n    var data = await res.json();\n    if (data.success) {\n      /* TMC_PATCH52_FIX: show post-delete newsletter signup screen. */\n      try { localStorage.clear(); } catch (e) {}\n      showPostDeleteSignup(\n        window.__tmcDelEmail || '',\n        window.__tmcDelName  || '',\n        reasonCode || ''\n      );\n    } else {\n      go.disabled = false; go.textContent = 'Permanently delete';\n      err.textContent = data.error || 'Failed to delete. Please contact support@tapmycar.io.';\n    }\n  } catch (e) {\n    go.disabled = false; go.textContent = 'Permanently delete';\n    err.textContent = 'Network error — please try again.';\n  }\n}\n\nasync function loadReferrals() {\n  try {\n    const res = await fetch('/api/get-referral?user_id=' + s.token);\n    const data = await res.json();\n    if (!data.success) return;\n    if (!data.referral_code) {\n      await fetch('/api/generate-referral-code', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ user_id: s.token }) });\n      setTimeout(loadReferrals, 1000);\n      return;\n    }\n    const link = 'https://tapmycar.io/r/' + data.referral_code; /* TMC_PATCH44 */\n    /* TMC_PATCH45A: populate the four-number grid from the new fields,\n       falling back to legacy fields if get-referral hasn't been redeployed. */\n    document.getElementById('ref-code').textContent = data.referral_code;\n    document.getElementById('ref-link').value = link;\n    var signups   = (typeof data.signups   === 'number') ? data.signups   : 0;\n    var confirmed = (typeof data.confirmed === 'number') ? data.confirmed : (data.referral_count || 0);\n    var avail     = (typeof data.credit_available === 'number') ? data.credit_available : (data.referral_credits || 0);\n    var pending   = (typeof data.credit_pending   === 'number') ? data.credit_pending   : 0;\n    document.getElementById('ref-signups').textContent   = signups;\n    document.getElementById('ref-confirmed').textContent = confirmed;\n    document.getElementById('ref-available').textContent = '$' + parseFloat(avail).toFixed(2);\n    document.getElementById('ref-pending').textContent   = '$' + parseFloat(pending).toFixed(2);\n    if (data.referral_reward_pending === 'choice') { document.getElementById('ref-reward-box').style.display = 'block'; }\n    /* TMC_PATCH45A_FIX: status line adapts to actual state. */\n    var nextEl = document.getElementById('ref-next');\n    if (signups === 0 && confirmed === 0) {\n      nextEl.textContent = 'Share your code  earn $3 credit when a friend buys a plan.';\n    } else if (confirmed === 0) {\n      nextEl.textContent = signups + ' friend' + (signups === 1 ? '' : 's') + ' signed up. Credits unlock when they buy a plan.';\n    } else if (pending > 0 && avail === 0) {\n      nextEl.textContent = '$' + parseFloat(pending).toFixed(2) + ' will unlock after the 14-day refund window.';\n    } else if (pending > 0 && avail > 0) {\n      nextEl.textContent = '$' + parseFloat(avail).toFixed(2) + ' ready to use. $' + parseFloat(pending).toFixed(2) + ' unlocks soon.';\n    } else {\n      nextEl.textContent = '$' + parseFloat(avail).toFixed(2) + ' available. Use it on your next purchase.';\n    }\n  } catch(e) { console.error(e); }\n}\n\nasync function claimReward(choice) {\n  const btn = document.getElementById('claim-' + choice);\n  btn.textContent = 'Claiming...'; btn.disabled = true;\n  try {\n    const res = await fetch('/api/claim-reward', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ user_id: s.token, choice }) });\n    const data = await res.json();\n    if (data.success) {\n      document.getElementById('ref-reward-box').style.display = 'none';\n      showToast(choice === 'free_standard' ? 'Free Standard credited!' : '$4.99 coupon applied!');\n      loadReferrals();\n    } else { showToast(data.error || 'Failed to claim'); }\n  } catch(e) { showToast('Network error'); }\n  btn.textContent = choice === 'free_standard' ? 'Free Standard' : '$4.99 Coupon';\n  btn.disabled = false;\n}\n\nfunction copyRefLink() {\n  navigator.clipboard.writeText(document.getElementById('ref-link').value).then(() => showToast('Link copied!')).catch(() => showToast('Copy failed'));\n}\n\nfunction shareRefLink() {\n  /* TMC_PATCH44: friendlier message + short URL. Passing the URL via\n     the canonical `url` field lets the OS share sheet render rich link\n     cards on iOS, while platforms that paste as plain text still get a\n     short URL (no query string) that they can preview reliably. */\n  const link = document.getElementById('ref-link').value;\n  if (!link) return;\n  const shareText = \"Hey! I'm on TapMyCar  the privacy-first contact tag for your car. Sign up with my referral:\";\n  if (navigator.share) {\n    navigator.share({ title: 'TapMyCar', text: shareText, url: link }).catch(function () { copyRefLink(); });\n  } else {\n    copyRefLink();\n  }\n}\n\nfunction signOut() { localStorage.clear(); window.location.href = '/signin.html'; }\n\nloadSettings();\nloadReferrals();\n</script>\n<script>if ('serviceWorker' in navigator) { navigator.serviceWorker.register('/sw.js'); }</script>\n\n<div style=\"padding:20px 20px 32px;text-align:center;border-top:.5px solid #E5E7EB;margin-top:24px;background:#fff\">\n  <p style=\"font-size:11px;color:#9CA3AF;margin:0 0 4px\">\n    <a href=\"/privacy.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Privacy</a>\n    &nbsp;·&nbsp;\n    <a href=\"/terms.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Terms</a>\n    &nbsp;·&nbsp;\n    <a href=\"mailto:support@tapmycar.io\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Support</a>\n  </p>\n  <p style=\"font-size:11px;color:#9CA3AF;margin:0\">© 2026 Praman Tech LLC</p>\n</div>\n\n<!-- Review Modal -->\n<div id=\"review-modal\" style=\"display:none;position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:1000;align-items:flex-end;justify-content:center\" onclick=\"if(event.target===this)closeReviewModal()\">\n  <div style=\"background:#fff;width:100%;max-width:430px;border-radius:20px 20px 0 0;padding:24px 20px;max-height:85vh;overflow-y:auto\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:16px\">\n      <div style=\"font-size:20px;font-weight:800;color:#111\">Share your experience</div>\n      <button onclick=\"closeReviewModal()\" style=\"background:none;border:none;font-size:24px;color:#9CA3AF;cursor:pointer;padding:4px\">×</button>\n    </div>\n    <div style=\"font-size:13px;color:#6B7280;margin-bottom:16px;line-height:1.5\">Your review will be visible after our team approves it. Reviews help others trust TapMyCar.</div>\n\n    <label style=\"font-size:12px;font-weight:700;color:#111;display:block;margin-bottom:6px\">Your name</label>\n    <input type=\"text\" id=\"rev-name\" placeholder=\"e.g. Sarah M.\" maxlength=\"60\" style=\"width:100%;height:42px;border:1.5px solid #E5E7EB;border-radius:11px;padding:0 12px;font-size:14px;margin-bottom:14px;font-family:inherit;box-sizing:border-box\">\n\n    <label style=\"font-size:12px;font-weight:700;color:#111;display:block;margin-bottom:6px\">City <span style=\"color:#9CA3AF;font-weight:400\">(optional)</span></label>\n    <input type=\"text\" id=\"rev-city\" placeholder=\"e.g. Hartford, CT\" maxlength=\"60\" style=\"width:100%;height:42px;border:1.5px solid #E5E7EB;border-radius:11px;padding:0 12px;font-size:14px;margin-bottom:14px;font-family:inherit;box-sizing:border-box\">\n\n    <label style=\"font-size:12px;font-weight:700;color:#111;display:block;margin-bottom:6px\">Your review</label>\n    <textarea id=\"rev-text\" placeholder=\"What do you love about TapMyCar? Share specifics about how it helped you.\" maxlength=\"500\" rows=\"5\" style=\"width:100%;border:1.5px solid #E5E7EB;border-radius:11px;padding:10px 12px;font-size:14px;margin-bottom:6px;font-family:inherit;resize:vertical;box-sizing:border-box\"></textarea>\n    <div style=\"font-size:11px;color:#9CA3AF;margin-bottom:16px\"><span id=\"rev-count\">0</span> / 500 characters (min 10)</div>\n\n    <button class=\"btn\" id=\"rev-submit-btn\" onclick=\"submitReview()\" style=\"margin-bottom:8px\">Submit review</button>\n    <button class=\"btn-o\" onclick=\"closeReviewModal()\">Cancel</button>\n  </div>\n</div>\n\n<script>\nfunction openReviewModal() {\n  if (!s || !s.token) { window.location.href = '/signin.html'; return; }\n  document.getElementById('rev-name').value = (localStorage.getItem('tmc_name') || '').slice(0, 60);\n  document.getElementById('rev-modal-update-count')();\n  document.getElementById('review-modal').style.display = 'flex';\n}\nfunction closeReviewModal() {\n  document.getElementById('review-modal').style.display = 'none';\n}\nasync function submitReview() {\n  const name = document.getElementById('rev-name').value.trim();\n  const city = document.getElementById('rev-city').value.trim();\n  const text = document.getElementById('rev-text').value.trim();\n\n  if (!name) { showToast('Please enter your name'); return; }\n  if (text.length < 10) { showToast('Review must be at least 10 characters'); return; }\n\n  const btn = document.getElementById('rev-submit-btn');\n  btn.textContent = 'Submitting...'; btn.disabled = true;\n\n  try {\n    const res = await fetch('/api/submit-review', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({ user_id: s.token, name, city, text })\n    });\n    const data = await res.json();\n    if (data.success) {\n      closeReviewModal();\n      showToast('Thank you! Your review is awaiting approval.');\n      document.getElementById('rev-text').value = '';\n      document.getElementById('rev-city').value = '';\n    } else {\n      showToast(data.error || 'Failed to submit review');\n    }\n  } catch (e) { showToast('Network error — please try again'); }\n  btn.textContent = 'Submit review'; btn.disabled = false;\n}\n\n// Live character count\nwindow.addEventListener('DOMContentLoaded', () => {\n  const ta = document.getElementById('rev-text');\n  const counter = document.getElementById('rev-count');\n  // Provide a wrapper that the open function can call\n  const updateCount = () => { counter.textContent = ta.value.length; };\n  document.getElementById('rev-modal-update-count') === null;\n  // Attach a no-arg handler accessible by id-style call we used above\n  Object.defineProperty(document.getElementById('rev-text'), 'updateCount', { value: updateCount });\n  ta.addEventListener('input', updateCount);\n  // Patch openReviewModal call to safely update\n  const realOpen = openReviewModal;\n  window.openReviewModal = function() {\n    if (!s || !s.token) { window.location.href = '/signin.html'; return; }\n    document.getElementById('rev-name').value = (localStorage.getItem('tmc_name') || '').slice(0, 60);\n    updateCount();\n    document.getElementById('review-modal').style.display = 'flex';\n  };\n});\n\n// Auto-open if user came via #leave-review hash\nwindow.addEventListener('load', () => {\n  if (window.location.hash === '#leave-review') {\n    setTimeout(() => openReviewModal(), 300);\n  }\n});\n</script>\n<script src=\"/tmc-redesign.js\"></script>\n\n<!-- TMC_FLOATING_NAV -->\n<nav class=\"tmc-fnav\" aria-label=\"Main navigation\">\n  <a href=\"/dashboard.html\" class=\"tmc-fnav-item\" data-match=\"/dashboard\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Home</span>\n  </a>\n  <a href=\"/manage.html\" class=\"tmc-fnav-item\" data-match=\"/manage\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Tag</span>\n  </a>\n  <a href=\"/verify.html\" class=\"tmc-fnav-item\" data-match=\"/verify\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Verify</span>\n  </a>\n  <a href=\"/activity.html\" class=\"tmc-fnav-item\" data-match=\"/activity\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Activity</span>\n  </a>\n  <a href=\"/settings.html\" class=\"tmc-fnav-item\" data-match=\"/settings\">\n    <div class=\"tmc-fnav-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg></div>\n    <span class=\"tmc-fnav-label\">Profile</span>\n  </a>\n</nav>\n<!-- /TMC_FLOATING_NAV -->\n<!-- TMC_PATCH46 renewal prompt -->\n<script src=\"/app-renewal-prompt.js\" defer></script>\n</body>\n</html>",
};

const MARKERS = {
  'public/help.html':     'TMC_SMART_BACK',
  'public/settings.html': 'TMC_HELP_PAGE',
};

let touched = 0;
for (const fp of Object.keys(FILES)) {
  const cur = fs.existsSync(fp) ? fs.readFileSync(fp, 'utf8') : '';
  if (cur.indexOf(MARKERS[fp]) !== -1 && fp.endsWith('settings.html')) {
    console.log(fp + ': skip (already patched)');
    continue;
  }
  if (fp.endsWith('help.html') && fs.existsSync(fp) && cur.indexOf('TMC_SMART_BACK') !== -1 && cur.length > 20000) {
    console.log(fp + ': skip (already exists)');
    continue;
  }
  fs.mkdirSync(path.join(BACKUP_DIR, path.dirname(fp)), { recursive: true });
  if (fs.existsSync(fp)) fs.copyFileSync(fp, path.join(BACKUP_DIR, fp));
  fs.writeFileSync(fp, FILES[fp], 'utf8');
  console.log(fp + ': written');
  touched++;
}

console.log('');
if (touched === 0) {
  console.log('Nothing to do  already patched.');
} else {
  console.log('Done. ' + touched + ' file(s) written. Backups in ' + BACKUP_DIR + '/');
  console.log('');
  console.log('NEXT STEPS:');
  console.log('  git add -A');
  console.log('  git commit -m "Add real Help & FAQ page, fix settings link"');
  console.log('  git push');
  console.log('');
  console.log('TEST after ~60s in fresh incognito:');
  console.log('  settings  Help & FAQ  opens /help.html');
  console.log('  Type in the search box  questions filter live');
  console.log('  Tap any question  answer expands; tap again  collapses');
  console.log('  Click "Back"  returns to settings (not dashboard)');
  console.log('  Click "Email support" at the bottom  opens mail client');
}
